package com.eventmanager.controller;
import com.eventmanager.util.DB; import com.eventmanager.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.*;
@WebServlet("/register") public class RegisterServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null||!"ATTENDEE".equals(u.role)){res.sendError(403);return;}try{int eventId=Integer.parseInt(req.getParameter("eventId"));int ticketId=Integer.parseInt(req.getParameter("ticketId"));try(Connection c=DB.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO registrations(event_id,attendee_id,ticket_id) VALUES(?,?,?)")){p.setInt(1,eventId);p.setInt(2,u.id);p.setInt(3,ticketId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE tickets SET quantity=quantity-1 WHERE id=? AND quantity>0")){p.setInt(1,ticketId);if(p.executeUpdate()==0)throw new SQLException("Ticket unavailable");}c.commit();}res.sendRedirect("dashboard");}catch(Exception e){throw new ServletException(e);}}}
